import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Normalize dtypes
    target_snapshot["status_ts"] = pd.to_datetime(target_snapshot["status_ts"])
    cdc_events["event_ts"] = pd.to_datetime(cdc_events["event_ts"])
    watermark["high_ts"] = pd.to_datetime(watermark["high_ts"])

    high_ts = watermark["high_ts"].iloc[0]

    # Build current state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Deterministic sequential processing per user by (event_ts, event_seq)
    new_events = new_events.sort_values(
        by=["user_id", "event_ts", "event_seq"], kind="mergesort"
    )

    seven_days = timedelta(days=7)

    for row in new_events.itertuples(index=False):
        uid = row.user_id
        op = row.op
        ts = row.event_ts
        email = row.email

        cur = state.get(uid)

        if op == "D":
            # Soft delete: status stays DELETED, status_ts updated, email preserved
            if cur is None:
                # No prior record; still record a deletion with the event's email
                # (no prior email to preserve)
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                state[uid] = {
                    "email": cur["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # cur status == 'DELETED'
                deletion_ts = cur["status_ts"]
                if ts > deletion_ts + seven_days:
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else: discard, deletion sticky within 7-day window
        # unknown ops ignored (none expected per spec)

    if state:
        records = [
            {
                "user_id": uid,
                "email": v["email"],
                "status": v["status"],
                "status_ts": v["status_ts"],
            }
            for uid, v in state.items()
        ]
        new_snapshot = pd.DataFrame(
            records, columns=["user_id", "email", "status", "status_ts"]
        )
    else:
        new_snapshot = pd.DataFrame(
            columns=["user_id", "email", "status", "status_ts"]
        )

    return {"new_snapshot": new_snapshot}
